import heapq

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Uses Dijkstra's algorithm to find the shortest path in a weighted directed graph.
    Returns the shortest distance and the path as a list of node names.
    """
    priority_queue = []
    heapq.heappush(priority_queue, (0, start))

    distances = {node: float('inf') for node in graph}
    distances[start] = 0

    previous_nodes = {node: None for node in graph}

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(priority_queue, (distance, neighbor))

    if distances[end] == float('inf'):
        return (float('inf'), [])

    path = []
    while end is not None:
        path.append(end)
        end = previous_nodes[end]
    path.reverse()

    return (distances[path[0]], path)

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Uses the Bellman-Ford algorithm to find the shortest path in a weighted directed graph.
    This algorithm handles negative weights and checks for negative cycles.
    Returns the shortest distance and the path as a list of node names.
    """
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    predecessors = {node: None for node in graph}

    # Relax edges up to (V - 1) times
    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    predecessors[neighbor] = node

    # Optionally detect negative weight cycles
    for node in graph:
        for neighbor, weight in graph[node]:
            if distances[node] + weight < distances[neighbor]:
                return (float('inf'), [])

    # Construct the shortest path
    if distances[end] == float('inf'):
        return (float('inf'), [])

    path = []
    while end is not None:
        path.append(end)
        end = predecessors[end]
    path.reverse()

    return (distances[path[0]], path)

