def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Uses a modified Depth-First Search (DFS) approach with backtracking to find the shortest path
    in a weighted directed graph. Returns the shortest distance and the path as a list of node names.
    """

    shortest_distance = float('inf')
    shortest_path = []

    def dfs(current_node: str, current_distance: float, path: list[str]):
        nonlocal shortest_distance, shortest_path

        if current_node == end:
            if current_distance < shortest_distance:
                shortest_distance = current_distance
                shortest_path = path.copy()
            return

        for neighbor, weight in graph.get(current_node, []):
            if neighbor not in path:  # Avoid cycles
                path.append(neighbor)
                dfs(neighbor, current_distance + weight, path)
                path.pop()  # Backtrack

    dfs(start, 0, [start])

    if shortest_distance == float('inf'):
        return (float('inf'), [])

    return (shortest_distance, shortest_path)

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Uses the Floyd-Warshall algorithm to identify the shortest paths between all pairs of nodes.
    After constructing the distance and path tables, it retrieves the shortest path from start to end.
    Returns the shortest distance and the path as a list of node names.
    """
    nodes = list(graph.keys())
    n = len(nodes)
    distances = {node: {other: float('inf') for other in nodes} for node in nodes}
    next_node = {node: {other: None for other in nodes} for node in nodes}

    for node in nodes:
        distances[node][node] = 0

    for node, edges in graph.items():
        for neighbor, weight in edges:
            distances[node][neighbor] = weight
            next_node[node][neighbor] = neighbor

    for k in nodes:
        for i in nodes:
            for j in nodes:
                if distances[i][j] > distances[i][k] + distances[k][j]:
                    distances[i][j] = distances[i][k] + distances[k][j]
                    next_node[i][j] = next_node[i][k]

    if distances[start][end] == float('inf'):
        return (float('inf'), [])

    path = []
    current = start
    while current is not None:
        path.append(current)
        if current == end:
            break
        current = next_node[current][end]

    return (distances[start][end], path)
